    kd_=kmarker(l,1,pi1,Wk_o); kh=kd_/np.linalg.norm(kd_); kdir[l]=kh
    Wk_p = Wk_o - np.outer(kh, kh@Wk_o)
    G_,O_,lab_=tokvecs(l, inf12, H12); y_=np.r_[np.ones(len(G_)),np.zeros(len(O_))]
    for nm_,Wk_ in [('orig',Wk_o),('kproj',Wk_p)] + ([('cur_edit',load(f'model.layers.{l}.self_attn.k_proj.weight').numpy())] if l==12 else []):
        kG,kO=G_@Wk_.T,O_@Wk_.T; dk=kG.mean(0)-kO.mean(0)
        print(l, nm_,'|dk|/|k| %.2f'%(np.linalg.norm(dk)/np.linalg.norm(kO,axis=1).mean()),'AUC %.3f'%roc_auc_score(y_,np.r_[kG@dk,kO@dk]), 'rel W change %.3f'%(np.linalg.norm(Wk_-Wk_o)/np.linalg.norm(Wk_o)))
