def lens_tok(l, i, t):
    h = np.asarray(Hl[l][i, dec_pos(T16[i], L16n[i])], dtype=np.float64)
    n = h/np.sqrt((h**2).mean()+1e-6)*(1+wn); return float(n @ Emb[t].numpy())
